DROP TABLE IF EXISTS `respuestas_encuestas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `respuestas_encuestas` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `referido_id` int(11) NOT NULL,
  `ronda_id` int(11) NOT NULL DEFAULT 1,
  `encuestadora_id` int(11) NOT NULL,
  `candidato_elegido` varchar(100) NOT NULL,
  `votante_yopal_respuesta` enum('Si','Quiero inscribir','No') NOT NULL,
  `observaciones` text DEFAULT NULL,
  `creado_en` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `referido_id` (`referido_id`),
  KEY `encuestadora_id` (`encuestadora_id`),
  CONSTRAINT `respuestas_encuestas_ibfk_1` FOREIGN KEY (`referido_id`) REFERENCES `referidos` (`id`) ON DELETE CASCADE,
  CONSTRAINT `respuestas_encuestas_ibfk_2` FOREIGN KEY (`encuestadora_id`) REFERENCES `usuarios` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=10156 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

